function getRegionColor(count: number, isSelected: boolean, isHovered: boolean): string {
  if (isSelected) return "#047857"
  if (isHovered) return "#059669"
  if (count >= 3) return "#10b981"
  if (count >= 2) return "#34d399"
  if (count >= 1) return "#6ee7b7"
  return "#d1fae5"
}

export default function MoroccoMap({
  onRegionSelect,
  selectedRegion,
  regionData,
}: MoroccoMapProps) {
  const [hoveredRegion, setHoveredRegion] = useState<string | null>(null)
  const tooltipRef = useRef<HTMLDivElement>(null)

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!tooltipRef.current) return
    const svg = e.currentTarget.getBoundingClientRect()
    tooltipRef.current.style.left = `${e.clientX - svg.left}px`
    tooltipRef.current.style.top = `${e.clientY - svg.top - 10}px`
  }

  return (
    <div className="relative w-full max-w-lg mx-auto">
      <svg
        viewBox="0 0 1000 1000"
        className="w-full h-auto drop-shadow-lg"
        onMouseMove={handleMouseMove}
      >
        {/* Background */}
        <defs>
          <filter id="shadow" x="-5%" y="-5%" width="110%" height="110%">
            <feDropShadow dx="0" dy="2" stdDeviation="3" floodOpacity="0.1" />
          </filter>
        </defs>

        {Object.entries(regions).map(([id, region]) => {
          // simplemaps uses specific region names, map them if needed or use as is
          const count = regionData[region.name] || 0
          const isSelected = selectedRegion === region.name
          const isHovered = hoveredRegion === id

          return (
            <path
              key={id}
              d={region.path}
              fill={getRegionColor(count, isSelected, isHovered)}
              stroke="white"
              strokeWidth="2"
              className="cursor-pointer transition-all duration-300"
              style={{
                filter: isSelected || isHovered ? "url(#shadow)" : "none",
                transform: isSelected || isHovered ? "scale(1.02)" : "scale(1)",
                transformOrigin: "center",
              }}
              onClick={() => onRegionSelect(isSelected ? "all" : region.name)}
              onMouseEnter={() => setHoveredRegion(id)}
              onMouseLeave={() => setHoveredRegion(null)}
            />
          )
        })}
      </svg>

      {/* Tooltip */}
      <div
        ref={tooltipRef}
        className={`absolute pointer-events-none z-20 bg-white rounded-xl shadow-xl border border-gray-100 px-4 py-3 transform -translate-x-1/2 -translate-y-full transition-opacity duration-200 ${
          hoveredRegion ? "opacity-100" : "opacity-0"
        }`}
        style={{ left: 0, top: 0 }}
      >
        {hoveredRegion && (
          <>
            <p className="text-sm font-heading font-bold text-gray-900">
              {regions[hoveredRegion].name}
            </p>
            <p className="text-xs text-gray-500">
              {regionData[regions[hoveredRegion].name] || 0} projets
            </p>
          </>
        )}
      </div>

      {/* Legend */}
      <div className="mt-6 flex flex-wrap justify-center gap-3">
        {[
          { color: "#d1fae5", label: "0 projet" },
          { color: "#6ee7b7", label: "1 projet" },
          { color: "#34d399", label: "2 projets" },
          { color: "#10b981", label: "3+ projets" },
        ].map((item) => (
          <div key={item.label} className="flex items-center gap-1.5">
            <div
              className="w-3 h-3 rounded-sm"
              style={{ backgroundColor: item.color }}
            />
            <span className="text-xs text-gray-500">{item.label}</span>
          </div>
        ))}
      </div>
    </div>
  )
}
